catalog_script_client.script:
/**
 * ClaimEase - Claim amount onChange (catalog client script)
 *
 * USABILITY ONLY: gives the employee immediate feedback that the amount must be
 * a number greater than zero. The authoritative check is
 * ClaimEaseValidator._validateAmount, which runs on the server for every
 * interface via the "Validate Claim" business rule.
 */
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return
    }

    g_form.hideFieldMsg('claim_amount', true)

    var raw = (newValue || '').toString().replace(/^\s+|\s+$/g, '')
    if (raw === '') {
        return
    }

    // Accept grouped input such as "1,250.00".
    var amount = parseFloat(raw.replace(/,/g, ''))

    if (isNaN(amount) || !isFinite(amount)) {
        g_form.showFieldMsg('claim_amount', 'Please enter the amount as a number, for example 24.50.', 'error')
        return
    }

    if (amount === 0) {
        g_form.showFieldMsg(
            'claim_amount',
            'The claim amount cannot be zero. Please enter the amount you actually spent.',
            'error'
        )
        return
    }

    if (amount < 0) {
        g_form.showFieldMsg('claim_amount', 'The claim amount must be a positive number.', 'error')
    }
}

/**
 * ClaimEase - Expense date onChange (catalog client script)
 *
 * USABILITY ONLY: warns the employee straight away that the expense date cannot
 * be in the future. The authoritative check is
 * ClaimEaseValidator._validateExpenseDate, which reads the
 * `allow_future_expense_date` property on the server. This script deliberately
 * cannot read that property (no GlideAjax), so it is only a hint: if an
 * administrator permits future dates, the server accepts the claim even though
 * the form showed this message.
 */
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return
    }

    g_form.hideFieldMsg('expense_incurred_on', true)

    var raw = (newValue || '').toString().replace(/^\s+|\s+$/g, '')
    if (raw === '') {
        return
    }

    var entered = parseIsoDate(raw)
    if (!entered) {
        // Unrecognised date format: say nothing and let the server decide.
        return
    }

    var today = new Date()
    today.setHours(0, 0, 0, 0)

    if (entered.getTime() > today.getTime()) {
        g_form.showFieldMsg(
            'expense_incurred_on',
            'The expense date cannot be in the future. Please enter the date you actually incurred the expense.',
            'error'
        )
    }

    /**
     * Service Portal supplies catalog date variables in the internal
     * yyyy-MM-dd format. Anything else is treated as unknown rather than
     * guessed at, so a dd/mm vs mm/dd locale can never produce a wrong warning.
     */
    function parseIsoDate(value) {
        var match = /^(\d{4})-(\d{2})-(\d{2})/.exec(value)
        if (!match) {
            return null
        }
        var year = parseInt(match[1], 10)
        var month = parseInt(match[2], 10) - 1
        var day = parseInt(match[3], 10)
        var date = new Date(year, month, day)
        date.setHours(0, 0, 0, 0)
        if (date.getFullYear() !== year || date.getMonth() !== month || date.getDate() !== day) {
            return null
        }
        return date
    }
}

/**
 * ClaimEase - Reimbursement claim form, onLoad (catalog client script)
 *
 * USABILITY ONLY. Nothing here is a security control: requested_for is forced
 * to the authenticated user by the record producer script, and every rule
 * hinted at below is enforced server-side by ClaimEaseValidator and the claim
 * business rules for every interface.
 */
function onLoad() {
    // Belt and braces alongside the variable's readOnly flag and the UI policy:
    // the employee submits for themselves, so there is nothing to choose here.
    if (g_form.hasField('requested_for_employee')) {
        g_form.setReadOnly('requested_for_employee', true)
    }

    // One short, friendly reminder of what makes a claim go through first time.
    g_form.addInfoMessage(
        'Tell us what you spent and when, then attach your receipt or supporting document before you submit. ' +
            'Your claim goes for approval as soon as it passes our automatic checks.'
    )
}

/**
 * ClaimEase - Reimbursement claim onSubmit checks (catalog client script)
 *
 * USABILITY ONLY, and synchronous by design (no GlideAjax: an async call never
 * completes before the form submits). Every check below is also performed
 * server-side by ClaimEaseValidator through the "Validate Claim" business rule,
 * so removing or bypassing this script changes nothing about what the platform
 * will accept.
 */
function onSubmit() {
    var problems = []

    var summary = value('claim_summary')
    var category = value('claim_category')
    var amountRaw = value('claim_amount')
    var expenseDate = value('expense_incurred_on')

    if (summary === '') {
        problems.push('Please tell us what you are claiming for.')
        g_form.showFieldMsg('claim_summary', 'Please tell us what you are claiming for.', 'error')
    }

    if (category === '') {
        problems.push('Please choose a claim category.')
        g_form.showFieldMsg('claim_category', 'Please choose a claim category.', 'error')
    }

    if (amountRaw === '') {
        problems.push('Please enter the claim amount.')
        g_form.showFieldMsg('claim_amount', 'Please enter the claim amount.', 'error')
    } else {
        var amount = parseFloat(amountRaw.replace(/,/g, ''))
        if (isNaN(amount) || !isFinite(amount)) {
            problems.push('Please enter the claim amount as a number, for example 24.50.')
            g_form.showFieldMsg('claim_amount', 'Please enter the amount as a number, for example 24.50.', 'error')
        } else if (amount <= 0) {
            problems.push('The claim amount must be greater than zero.')
            g_form.showFieldMsg('claim_amount', 'The claim amount must be greater than zero.', 'error')
        }
    }

    if (expenseDate === '') {
        problems.push('Please enter the date you incurred the expense.')
        g_form.showFieldMsg('expense_incurred_on', 'Please enter the date you incurred the expense.', 'error')
    }

    if (problems.length > 0) {
        g_form.addErrorMessage(
            problems.length === 1
                ? problems[0]
                : 'Your claim is not quite ready: ' + problems.join(' ')
        )
        return false
    }

    return true

    function value(name) {
        if (!g_form.hasField(name)) {
            return ''
        }
        return (g_form.getValue(name) || '').toString().replace(/^\s+|\s+$/g, '')
    }
}
